 return f'''<div class="size-control"><label>Размер бани <select data-size-picker="{m}" aria-label="Размер {names[m]}">{opts}</select></label></div><div class="price-line"><div><strong data-price="{m}">{money(price(m,s))}</strong><small>Комплектация «Комфорт»</small></div>{request(m=m,s=s)}</div><p class="caption" style="margin-top:12px">Доставка, разгрузка, основание и внешние подключения рассчитываются отдельно.</p><div class="model-foot"><a class="textlink" href="{model_url(m)}">{'О модели и оснащении' if not full else 'Подробнее о модели'} →</a><button class="textlink" data-save="{m}" type="button" style="border:0;background:none;font-size:13px">Сохранить выбор</button></div><details class="disclosure"><summary>Все размеры и цены</summary><table class="price-table"><caption class="caption">{names[m]} · Комфорт</caption><tbody>{table}</tbody></table></details>'''
